def transform(grid):
    out = [row[:] for row in grid]
    r, c = next((r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1)
    tr, tc = next((r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2)

    dr = 1 if tr > r else -1
    dc = 1 if tc > c else -1
    nr, nc = abs(tr - r), abs(tc - c)

    # Travel diagonally as far as possible, stopping adjacent to the nearer axis;
    # then continue straight until diagonally adjacent to the 2.
    for _ in range(max(0, min(nr, nc) - 1)):
        r += dr
        c += dc
        out[r][c] = 3

    while (r, c) != (tr - dr, tc - dc):
        if abs(tr - r) > abs(tc - c):
            r += dr
        else:
            c += dc
        if (r, c) != (tr, tc):
            out[r][c] = 3

    return out
